/-- The rider's measured relation to the subject in `blind` at instant k (offset 18 − 5k m): the
    bearing (longitudinal, lateral) in the subject's frame, the shared projection length on the
    subject's heading, headings aligned — the values the forbid geometry gives. At k = 4 the subject
    has turned to heading (10, −1), whose unit vector Core reads as (10⁶, −10⁵)/1004987: the bearing
    is (−1.5, −5.2)·10⁶/1004987 and the overlap (2.525·10¹² − 0.47·10⁶·1004987)/1004987². -/
def blindRelation (k : Nat) : MeasuredRelation :=
  let dx : Int := 18 - 5 * (k : Int)
  let bearing : Vec :=
    if k < 4 then (m dx, m (-5)) else (Units.ratio (-1500000) 1004987, Units.ratio (-5200000) 1004987)
  let overlap : Q :=
    if k < 4 then cm (350 - 100 * (dx.natAbs : Int)) else Units.ratio 2052656110000 1009998870169
  Build.relation 1 2 fun r =>
    { r with bearing := some bearing
             longitudinalOverlap := some overlap
             sameDirection := some true }

/-- `blind` (unknown): As in forbid, but the source does not observe headings (the manifest masks
    kin.heading). The source measures the relation of the rider to the subject itself (bearing,
    longitudinal overlap, aligned headings), so the selection is decided and only the subject's
    heading against the lane is unknown. -/
def blindTrace : Trace :=
  (passTrace 5 .bicycle riderHalf 1 18 4 oneLaneRoad).zipIdx.map fun (s, k) =>
    Build.withRelations s [blindRelation k]

